//! The CALLBACKS of a durable execution: the id a handler's `wait_for_callback` mints, the
//! window it is open for, and what a client signalling it does to the execution's history.
//!
//! # The rule this module implements
//!
//! A durable function can wait for something OUTSIDE itself to finish: the durable context
//! mints a callback id — "Callback IDs are generated by the `DurableContext` when a durable
//! function calls `ctx.waitForCallback`" (`CallbackStartedDetails$CallbackId`) — the execution
//! takes a `CallbackStarted` history event carrying that id and the timeouts the call was
//! configured with (`CallbackOptions`: "the timeout for the callback operation in seconds. If
//! not specified or set to 0, the callback has no timeout" and "the heartbeat timeout … If not
//! specified or set to 0, heartbeat timeout is disabled"), and the handler then waits.
//!
//! What happens next is a CLIENT's to decide, through the three operations that address the
//! callback by that id: `SendDurableExecutionCallbackSuccess` carries the result the waiting
//! handler receives, `SendDurableExecutionCallbackFailure` the error it raises, and
//! `SendDurableExecutionCallbackHeartbeat` says the external work is still running, which is
//! what the heartbeat timeout is measured from. Each of them is accepted exactly once and only
//! while the callback is OPEN: past the window `CallbackTimeoutException` is what a caller is
//! told — "the callback ID token has either expired or the callback associated with the token
//! has already been closed" — and an id no callback of this emulator was ever minted for is
//! `ResourceNotFoundException`, the resource the request names not existing.
//!
//! The move from open to timed out is owed by the CLOCK rather than by anybody calling, exactly
//! as a durable execution's own `ExecutionTimeout` is: [`DurableExecutionRecord::materialize`]
//! applies whatever the clock has already made due, so a callback whose window closed takes its
//! `CallbackTimedOut` event at the instant it closed, whoever reads the execution next.
//!
//! # How a callback is addressed
//!
//! The id is an opaque token the client only ever sends back ([`mint_callback_id`]): it carries
//! the function, the execution and the operation it belongs to, so a client holding nothing but
//! that id addresses the one callback it was minted for. The stored callback is what makes it
//! real — an id that decodes but names no stored callback is not found — so nothing about a
//! callback is read out of the token itself.

use super::*;

/// The `OperationType` of the wait a durable handler takes through `context.wait_for_callback`
/// (`smithy_query(query="shape", shape="OperationType")`: `EXECUTION`, `CONTEXT`, `STEP`,
/// `WAIT`, `CALLBACK`, `CHAINED_INVOKE`).
pub const CALLBACK_TYPE: &str = "CALLBACK";

/// The model's `EventType` for a callback that was minted and is now waiting
/// (`smithy_query(query="shape", shape="EventType")`).
pub const EVENT_TYPE_CALLBACK_STARTED: &str = "CallbackStarted";

/// The model's `EventType` for a callback a client completed; see
/// [`EVENT_TYPE_CALLBACK_STARTED`].
pub const EVENT_TYPE_CALLBACK_SUCCEEDED: &str = "CallbackSucceeded";

/// The model's `EventType` for a callback a client failed; see
/// [`EVENT_TYPE_CALLBACK_STARTED`].
pub const EVENT_TYPE_CALLBACK_FAILED: &str = "CallbackFailed";

/// The model's `EventType` for a callback whose window closed before anybody signalled it; see
/// [`EVENT_TYPE_CALLBACK_STARTED`].
pub const EVENT_TYPE_CALLBACK_TIMED_OUT: &str = "CallbackTimedOut";

/// How many callbacks ONE execution may mint.
///
/// Every callback a handler takes is held on the execution for as long as the execution is
/// held, so the number of them is bounded here rather than by how many a handler asks for. It
/// is the number of events one execution's history may be grown by
/// ([`durable_steps::MAX_STEP_EVENTS`]), past which a callback's own events could not be
/// recorded anyway.
pub const MAX_EXECUTION_CALLBACKS: usize = durable_steps::MAX_STEP_EVENTS;

/// The longest a callback's OPERATION ID may be, in bytes: the model's own `OperationId`
/// length (`smithy_query(query="shape", shape="OperationUpdate")`: `@length(min: 1, max: 64)`).
const MAX_OPERATION_ID_BYTES: usize = 64;

/// The longest its NAME may be, in bytes: the model's own `OperationName` length
/// (`@length(min: 1, max: 256)`), which is also what a read reports it as.
const MAX_OPERATION_NAME_BYTES: usize = 256;

/// What a callback is waiting for, or what it came to.
pub const CALLBACK_STATE_WAITING: &str = "WAITING";
/// See [`CALLBACK_STATE_WAITING`].
pub const CALLBACK_STATE_SUCCEEDED: &str = "SUCCEEDED";
/// See [`CALLBACK_STATE_WAITING`].
pub const CALLBACK_STATE_FAILED: &str = "FAILED";
/// See [`CALLBACK_STATE_WAITING`].
pub const CALLBACK_STATE_TIMED_OUT: &str = "TIMED_OUT";

/// What a caller sending to a callback that is no longer open is told.
///
/// The SERVICE's own sentence for this error class, which answers both of the two reasons the
/// model gives `CallbackTimeoutException` ("the callback ID token has either expired or the
/// callback associated with the token has already been closed") with one wording about the
/// callback itself: a window that closed and a callback a client has already signalled are told
/// the same thing.
pub const CALLBACK_CLOSED_MESSAGE: &str = "The callback is either timed out or already completed";

/// The error a callback that TIMED OUT carries, which is what the waiting handler is told and
/// what `CallbackTimedOutDetails$Error` reports.
pub const CALLBACK_TIMED_OUT_ERROR_TYPE: &str = "CallbackTimeout";

/// What one CALLBACK of a durable execution is: the operation it belongs to, the window it is
/// open for, and what it came to.
///
/// Held per execution on [`DurableExecutionRecord::callbacks`] and keyed by the id the handler's
/// durable context minted for it, which is what a client addresses it by.
#[derive(Debug, Clone)]
pub struct CallbackRecord {
    /// The operation's own id, which the history events of this callback carry as `Event$Id`.
    pub operation_id: String,
    /// The operation's customer-provided name, where the handler named one.
    pub name: Option<String>,
    /// When the callback was minted, which `Operation$StartTimestamp` reports for it.
    pub started: SystemTime,
    /// When it closed, which `Operation$EndTimestamp` reports; absent while it is open.
    pub ended: Option<SystemTime>,
    /// Whether a checkpoint has already reported this callback's own completion as an
    /// operation "updated since the last checkpoint"
    /// (`CheckpointDurableExecution$NewExecutionState`), so one completion is reported once.
    pub reported: bool,
    /// The `TimeoutSeconds` the callback was configured with, and `None` for one configured
    /// with none: "if not specified or set to 0, the callback has no timeout".
    pub timeout_seconds: Option<i32>,
    /// The `HeartbeatTimeoutSeconds` it was configured with, and `None` where heartbeats are
    /// disabled: "if not specified or set to 0, heartbeat timeout is disabled".
    pub heartbeat_timeout_seconds: Option<i32>,
    /// When the whole callback's window closes, while it is open and a timeout was configured.
    pub timeout_due: Option<SystemTime>,
    /// When the next heartbeat is due, while it is open and a heartbeat timeout was
    /// configured: the heartbeat timeout after the last heartbeat, or after the start where
    /// none has arrived.
    pub heartbeat_due: Option<SystemTime>,
    /// What the callback is waiting for or came to ([`CALLBACK_STATE_WAITING`]).
    pub state: String,
    /// The `Result` the client that completed it carried, as the text the history reports.
    pub result: Option<String>,
    /// The `Error` the client that failed it carried, or the one the timeout is.
    pub error: Option<ErrorObject>,
}

impl CallbackRecord {
    /// Whether this callback is still OPEN: one a client may signal, and one the handler
    /// waiting on it is still waiting for.
    #[must_use]
    pub fn is_waiting(&self) -> bool {
        self.state == CALLBACK_STATE_WAITING
    }
}

/// A fresh callback id for the operation `operation` of the execution `execution` of
/// `function`.
///
/// The model's `CallbackId` is `@length(1, 1024)` and `^[A-Za-z0-9+/]+={0,2}$`, and the id
/// travels in a request's URI, so it is written as HEXADECIMAL — inside that pattern and with
/// no character a path or a query could read differently. What it carries is the three names
/// that locate the callback plus the id of the execution it belongs to, so a client holding
/// nothing but the token addresses the one callback it was minted for; the STORED callback is
/// what makes it real.
#[must_use]
pub fn mint_callback_id(
    function: &str,
    execution: &str,
    execution_id: &str,
    operation: &str,
) -> String {
    ::hex::encode(
        [function, execution, execution_id, operation]
            .join(CALLBACK_ID_SEPARATOR)
            .as_bytes(),
    )
}

/// What the parts of a callback id are separated by inside it: a character no function name, no
/// execution name and no operation id may carry (`FunctionName`, `DurableExecutionName` and
/// `OperationId` are all printable), so the parts cannot run together.
const CALLBACK_ID_SEPARATOR: &str = "\u{1f}";

/// Where a callback id says its callback is: the function, the execution and the operation.
#[derive(Debug, Clone)]
pub struct CallbackAddress {
    /// The function the execution belongs to.
    pub function: String,
    /// The execution's own name.
    pub execution: String,
    /// The id the execution was minted with, checked against the stored one so an id naming
    /// the right name under a different execution addresses nothing.
    pub execution_id: String,
}

/// Where `callback_id` says its callback is, and `None` for text that is no id this emulator
/// minted.
///
/// The value is UNTRUSTED request text: it is only ever decoded and split, so no input can make
/// this panic, and an id that decodes to a shape this never minted addresses nothing.
#[must_use]
pub fn callback_address(callback_id: &str) -> Option<CallbackAddress> {
    let decoded = ::hex::decode(callback_id).ok()?;
    let decoded = String::from_utf8(decoded).ok()?;
    let mut parts = decoded.split(CALLBACK_ID_SEPARATOR);
    let function = parts.next()?.to_string();
    let execution = parts.next()?.to_string();
    let execution_id = parts.next()?.to_string();
    // The operation id follows, and nothing else: an id carrying more parts than the mint
    // writes is not one of this emulator's.
    parts.next()?;
    if parts.next().is_some() || function.is_empty() || execution.is_empty() {
        return None;
    }
    Some(CallbackAddress {
        function,
        execution,
        execution_id,
    })
}

impl DurableExecutionRecord {
    /// Close every callback of this execution whose window the CLOCK has already closed, and
    /// append the `CallbackTimedOut` event each closing is.
    ///
    /// The transition is owed by the clock: a callback whose `TimeoutSeconds` have passed since
    /// it was minted, or whose `HeartbeatTimeoutSeconds` have passed since the last heartbeat,
    /// is closed — "the callback ID token has either expired" — and it would have been owed at
    /// the same instant even if nobody had called. The event is timed at the instant the window
    /// closed rather than at the call that noticed it.
    ///
    /// Nothing is closed on an execution that is no longer running: its history is closed, and
    /// a callback of it can take no further event.
    pub fn timeout_callbacks(&mut self, now: SystemTime) {
        if self.status != EXECUTION_STATUS_RUNNING {
            return;
        }
        let closed: Vec<(String, SystemTime)> = self
            .callbacks
            .iter()
            .filter(|(_id, callback)| callback.is_waiting())
            .filter_map(|(id, callback)| {
                let due = [callback.timeout_due, callback.heartbeat_due]
                    .into_iter()
                    .flatten()
                    .filter(|due| now >= *due)
                    .min()?;
                Some((id.clone(), due))
            })
            .collect();
        for (id, due) in closed {
            let error = ErrorObject {
                error_type: Some(CALLBACK_TIMED_OUT_ERROR_TYPE.to_string()),
                error_message: Some(CALLBACK_CLOSED_MESSAGE.to_string()),
                ..ErrorObject::default()
            };
            let Some(callback) = self.callbacks.get_mut(&id) else {
                continue;
            };
            callback.state = CALLBACK_STATE_TIMED_OUT.to_string();
            callback.timeout_due = None;
            callback.heartbeat_due = None;
            callback.ended = Some(due);
            callback.error = Some(error.clone());
            let operation = callback.operation_id.clone();
            let name = callback.name.clone();
            let checkpoint = durable_steps::Checkpoint {
                operation: CALLBACK_TYPE.to_string(),
                action: durable_steps::CANCEL_ACTION.to_string(),
                id: Some(operation),
                name,
                attempt: 1,
                error: Some(error),
                ..durable_steps::Checkpoint::default()
            };
            durable_steps::append_checkpoint(self, &checkpoint, due);
        }
    }
}

/// What one callback is waiting for or came to, as the run that is waiting on it reads it.
///
/// The members are the callback's own state and whatever it came to: the result a client
/// completed it with, or the error it failed or timed out with.
#[must_use]
pub fn callback_answer(callback: &CallbackRecord) -> ::serde_json::Value {
    let error = callback.error.as_ref().map(|error| {
        ::serde_json::json!({
            "errorType": error.error_type,
            "errorMessage": error.error_message,
        })
    });
    ::serde_json::json!({
        "state": callback.state,
        "result": callback.result,
        "error": error,
    })
}

/// ONE call the RUN of a durable execution made about a callback of it, answered as the
/// document the runtime's own durable SDK reads ([`super::execution::durable_sdk_guest`]).
///
/// Two calls: `START` MINTS the callback the handler is about to wait on — registering it,
/// appending the `CallbackStarted` event its id travels in, and answering that id — and `POLL`
/// answers what that callback has come to while the handler waits. A run of an execution this
/// store no longer holds mints nothing and polls nothing.
#[must_use]
pub fn answered_for_run(
    state: &::engine::ServiceState<ComAmazonawsLambdaAwsgirapiserviceState>,
    function: &str,
    execution: &str,
    document: &str,
) -> String {
    let asked = ::serde_json::from_str::<::serde_json::Value>(document).unwrap_or_default();
    let action = asked
        .get("action")
        .and_then(::serde_json::Value::as_str)
        .unwrap_or_default();
    let answered = match action {
        "START" => started_for_run(state, function, execution, &asked),
        "POLL" => polled_for_run(state, function, execution, &asked),
        other => Err(format!(
            "{other} is not a call a run makes about a callback of its execution"
        )),
    };
    match answered {
        Ok(answer) => answer.to_string(),
        // The REFUSAL of the call itself, under a member of its own: a callback that FAILED
        // carries an error too, and the two are not the same thing.
        Err(detail) => ::serde_json::json!({ "refused": detail }).to_string(),
    }
}

/// MINT the callback the handler is about to wait on, and answer the id a client signals it by.
fn started_for_run(
    state: &::engine::ServiceState<ComAmazonawsLambdaAwsgirapiserviceState>,
    function: &str,
    execution: &str,
    asked: &::serde_json::Value,
) -> Result<::serde_json::Value, String> {
    let text = |name: &str| {
        asked
            .get(name)
            .and_then(::serde_json::Value::as_str)
            .map(str::to_string)
    };
    let seconds = |name: &str| {
        asked
            .get(name)
            .and_then(::serde_json::Value::as_i64)
            .and_then(|seconds| i32::try_from(seconds).ok())
            // "If not specified or set to 0, the callback has no timeout" — and the same for
            // the heartbeat timeout, which 0 disables.
            .filter(|seconds| *seconds > 0)
    };
    let operation = text("id").ok_or_else(|| "the callback named no operation".to_string())?;
    // The operation's own id and name are the model's own members, so they are held to the
    // lengths it gives them (`OperationUpdate$Id` is `@length(1, 64)` and `$Name`
    // `@length(1, 256)`): a handler decides what it names its waits, and what one callback can
    // add to the store is bounded here rather than by that choice.
    if operation.is_empty() || operation.len() > MAX_OPERATION_ID_BYTES {
        return Err(format!(
            "a callback's operation id carries at most {MAX_OPERATION_ID_BYTES} bytes"
        ));
    }
    let name = text("name").filter(|name| !name.is_empty());
    if name.as_ref().is_some_and(|name| name.len() > MAX_OPERATION_NAME_BYTES) {
        return Err(format!(
            "a callback's name carries at most {MAX_OPERATION_NAME_BYTES} bytes"
        ));
    }
    let timeout_seconds = seconds("timeoutSeconds");
    let heartbeat_timeout_seconds = seconds("heartbeatTimeoutSeconds");
    let now = execution_instant(SystemTime::now());
    let mut store = state.lock();
    let held = store
        .functions
        .get_mut(function)
        .and_then(|function| function.durable_executions.get_mut(execution))
        .ok_or_else(|| "this run's durable execution is no longer held".to_string())?;
    // Whatever the clock already owed is applied first, so a callback is never minted onto an
    // execution whose own timeout has fallen due.
    held.materialize(now);
    if held.status != EXECUTION_STATUS_RUNNING {
        return Err("this run's durable execution is no longer running".to_string());
    }
    if held.callbacks.len() >= MAX_EXECUTION_CALLBACKS {
        return Err(format!(
            "one durable execution may mint {MAX_EXECUTION_CALLBACKS} callbacks"
        ));
    }
    let callback_id = mint_callback_id(function, execution, &held.execution_id, &operation);
    let due = |configured: Option<i32>| {
        configured
            .and_then(|seconds| u64::try_from(seconds).ok())
            .and_then(|seconds| now.checked_add(Duration::from_secs(seconds)))
    };
    held.callbacks.insert(
        callback_id.clone(),
        CallbackRecord {
            operation_id: operation.clone(),
            name: name.clone(),
            started: now,
            ended: None,
            reported: false,
            timeout_seconds,
            heartbeat_timeout_seconds,
            timeout_due: due(timeout_seconds),
            // The first heartbeat is due that span after the callback was minted, which is
            // what "the heartbeat timeout for the callback operation" is measured from until
            // one arrives.
            heartbeat_due: due(heartbeat_timeout_seconds),
            state: CALLBACK_STATE_WAITING.to_string(),
            result: None,
            error: None,
        },
    );
    // The history records what happened: the callback that STARTED, carrying the id a client
    // signals it by and the timeouts it was configured with.
    let checkpoint = durable_steps::Checkpoint {
        operation: CALLBACK_TYPE.to_string(),
        action: durable_steps::START_ACTION.to_string(),
        id: Some(operation),
        name,
        attempt: 1,
        callback_id: Some(callback_id.clone()),
        callback_timeout_seconds: timeout_seconds,
        callback_heartbeat_timeout_seconds: heartbeat_timeout_seconds,
        ..durable_steps::Checkpoint::default()
    };
    durable_steps::append_checkpoint(held, &checkpoint, now);
    Ok(::serde_json::json!({ "callbackId": callback_id }))
}

/// What the callback the run is waiting on has come to.
///
/// Reading it is also what applies whatever the CLOCK already made due, so a handler waiting
/// past the callback's window is told the callback timed out — at the instant it timed out —
/// rather than waiting for something that can no longer arrive.
fn polled_for_run(
    state: &::engine::ServiceState<ComAmazonawsLambdaAwsgirapiserviceState>,
    function: &str,
    execution: &str,
    asked: &::serde_json::Value,
) -> Result<::serde_json::Value, String> {
    let callback_id = asked
        .get("callbackId")
        .and_then(::serde_json::Value::as_str)
        .ok_or_else(|| "the call named no callback".to_string())?
        .to_string();
    let now = execution_instant(SystemTime::now());
    let mut store = state.lock();
    let held = store
        .functions
        .get_mut(function)
        .and_then(|function| function.durable_executions.get_mut(execution))
        .ok_or_else(|| "this run's durable execution is no longer held".to_string())?;
    held.materialize(now);
    let callback = held
        .callbacks
        .get(&callback_id)
        .ok_or_else(|| "this run holds no such callback".to_string())?;
    Ok(callback_answer(callback))
}

/// Whether the document [`answered_for_run`] built reports a callback that is still WAITING:
/// one no client has signalled and whose window has not closed.
///
/// Read by the seam the run asks over ([`super::execution::python`]), which is what waits
/// between two readings of a callback that is still open — a wait the EXECUTION takes rather
/// than the invocation, since a durable execution suspends while it waits for something outside
/// itself. An answer that is no reading of a callback's state at all — the refusal of the call,
/// the id a mint answered — reports no callback waiting.
#[must_use]
pub fn answer_is_still_waiting(answered: &str) -> bool {
    ::serde_json::from_str::<::serde_json::Value>(answered)
        .ok()
        .as_ref()
        .and_then(|answer| answer.get("state"))
        .and_then(::serde_json::Value::as_str)
        == Some(CALLBACK_STATE_WAITING)
}

/// The same answer, saying whether the host WAITED inside this reading.
///
/// The run reads a callback it is waiting on in a LOOP, so the one thing that loop has to know
/// about a reading is whether the wait before the next one has already been taken: a reading the
/// host waited inside costs the guest nothing to take again, and one it did not — because what a
/// run may sit suspended for is spent ([`super::execution::CALLBACK_SUSPENSION_CEILING`]) — is
/// one the guest waits after itself, through the sleep this runtime clamps to what the run has
/// left. That is what bounds the loop: every turn of it either waits here or waits there, and a
/// wait the run is charged for brings its own deadline closer.
///
/// The member is added to the answer rather than replacing it, so what the reading says about
/// the callback is untouched; an answer that is no JSON object is left exactly as it was.
#[must_use]
pub fn answer_waited(answered: &str, waited: bool) -> String {
    let Ok(::serde_json::Value::Object(mut answer)) =
        ::serde_json::from_str::<::serde_json::Value>(answered)
    else {
        return answered.to_string();
    };
    answer.insert(ANSWER_WAITED_MEMBER.to_string(), ::serde_json::json!(waited));
    ::serde_json::Value::Object(answer).to_string()
}

/// The member [`answer_waited`] carries that in, which the runtime's own durable SDK reads.
const ANSWER_WAITED_MEMBER: &str = "waited";

/// The refusal a `CallbackId` that addresses no callback this emulator holds gets: the
/// canonical sentence every Lambda resource-shaped refusal follows, naming the resource the
/// request asked about (compare the `Durable execution not found: <arn>`
/// [`durable_execution_not_found_message`] builds).
#[must_use]
pub fn callback_not_found_message(callback_id: &str) -> String {
    format!("Callback not found: {callback_id}")
}

/// The customer managed key the data a callback carries is stored under: the one the
/// `DurableConfig` of the execution that minted it names, and `None` for an execution under no
/// key of its own or an id that addresses none.
#[must_use]
pub fn callback_data_key(
    state: &::engine::ServiceState<ComAmazonawsLambdaAwsgirapiserviceState>,
    callback_id: &str,
) -> Option<String> {
    let address = callback_address(callback_id)?;
    let store = state.lock();
    store
        .functions
        .get(&address.function)
        .and_then(|function| function.durable_executions.get(&address.execution))
        .filter(|execution| execution.execution_id == address.execution_id)
        .and_then(|execution| execution.kms_key_arn.clone())
}

/// The callbacks of `execution` that have CLOSED and have not been reported to a checkpoint
/// yet, as the operations `CheckpointDurableExecution` answers.
///
/// `NewExecutionState` is "operations that have been updated since the last checkpoint, such as
/// completed asynchronous work like timers or callbacks", so a callback a client signalled —
/// or one whose window the clock closed — between two checkpoints is reported to the next one,
/// carrying what it came to. Each completion is reported ONCE: the record remembers that it
/// was, so the checkpoint after it is not told the same thing again.
pub fn callbacks_updated_since_last_checkpoint(
    execution: &mut DurableExecutionRecord,
) -> Vec<crate::ops::Operation> {
    // Taken as a snapshot first, so what is reported is read off the record and the record is
    // then marked as having been reported, in one pass each.
    let closed: Vec<(String, CallbackRecord)> = execution
        .callbacks
        .iter()
        .filter(|(_id, callback)| !callback.reported && !callback.is_waiting())
        .map(|(id, callback)| (id.clone(), callback.clone()))
        .collect();
    let mut updated = Vec::with_capacity(closed.len());
    for (callback_id, callback) in closed {
        if let Some(held) = execution.callbacks.get_mut(&callback_id) {
            held.reported = true;
        }
        updated.push(crate::ops::Operation {
            id: callback.operation_id.clone(),
            parent_id: None,
            name: callback.name.clone(),
            r#type: CALLBACK_TYPE.to_string(),
            sub_type: None,
            start_timestamp: ::aws_smithy_types::DateTime::from(callback.started),
            end_timestamp: callback.ended.map(::aws_smithy_types::DateTime::from),
            // The `OperationStatus` the callback's own state is
            // (`smithy_query(query="shape", shape="OperationStatus")`: `STARTED`, `PENDING`,
            // `READY`, `SUCCEEDED`, `FAILED`, `CANCELLED`, `TIMED_OUT`, `STOPPED`).
            status: match callback.state.as_str() {
                CALLBACK_STATE_SUCCEEDED => "SUCCEEDED",
                CALLBACK_STATE_FAILED => "FAILED",
                _ => "TIMED_OUT",
            }
            .to_string(),
            execution_details: None,
            context_details: None,
            step_details: None,
            wait_details: None,
            // "Contains details about a callback operation": the id a client signalled and
            // what that signal carried.
            callback_details: Some(crate::ops::CallbackDetails {
                callback_id: Some(callback_id),
                result: callback.result.clone(),
                error: callback.error.clone(),
            }),
            chained_invoke_details: None,
        });
    }
    updated
}

/// What a client signalling a callback did to it.
#[derive(Debug, Clone)]
pub enum CallbackSignal {
    /// The external work finished, carrying what it produced
    /// (`SendDurableExecutionCallbackSuccess$Result`).
    Succeeded(Option<String>),
    /// The external work failed, carrying the error the client gave
    /// (`SendDurableExecutionCallbackFailure$Error`).
    Failed(Option<ErrorObject>),
    /// The external work is still running, which is what the heartbeat timeout is measured
    /// from ("sends a heartbeat for a callback operation to indicate that the external system
    /// is still processing").
    Heartbeat,
}

/// Why a client's signal was not accepted.
#[derive(Debug, Clone)]
pub enum CallbackRefusal {
    /// No callback of this emulator is addressed by that id: the resource the request names
    /// does not exist, which is the modelled `ResourceNotFoundException`.
    NotFound,
    /// The callback is no longer open — its window closed, or it has already been signalled —
    /// which is the modelled `CallbackTimeoutException`.
    Closed,
}

/// Apply `signal` to the callback `callback_id` addresses, at `now`.
///
/// The callback is addressed by the id alone, which is all a client holds: the id says where it
/// is ([`callback_address`]) and the STORED callback is what makes it real, so an id that
/// decodes but names no callback this emulator holds is not found. Resolving it is also what
/// brings the execution up to whatever the clock already made due, so a signal arriving after
/// the callback's window closed meets a callback that is already closed.
///
/// A signal that is ACCEPTED appends the history event it is — the callback that succeeded or
/// failed — and a heartbeat moves the instant the next one is due. Nothing here invents a
/// transition: a callback that is not open takes none.
pub fn signal_callback(
    state: &::engine::ServiceState<ComAmazonawsLambdaAwsgirapiserviceState>,
    callback_id: &str,
    signal: &CallbackSignal,
    now: SystemTime,
) -> Result<(), CallbackRefusal> {
    let address = callback_address(callback_id).ok_or(CallbackRefusal::NotFound)?;
    let now = execution_instant(now);
    let mut store = state.lock();
    let execution = store
        .functions
        .get_mut(&address.function)
        .and_then(|function| function.durable_executions.get_mut(&address.execution))
        .filter(|execution| execution.execution_id == address.execution_id)
        .ok_or(CallbackRefusal::NotFound)?;
    // Whatever the clock already owed is applied first: a signal reaching a callback whose
    // window has closed meets the closed callback rather than re-opening it.
    execution.materialize(now);
    if !execution.callbacks.contains_key(callback_id) {
        return Err(CallbackRefusal::NotFound);
    }
    if execution.status != EXECUTION_STATUS_RUNNING {
        return Err(CallbackRefusal::Closed);
    }
    let callback = execution
        .callbacks
        .get_mut(callback_id)
        .ok_or(CallbackRefusal::NotFound)?;
    if !callback.is_waiting() {
        return Err(CallbackRefusal::Closed);
    }
    let operation = callback.operation_id.clone();
    let name = callback.name.clone();
    let checkpoint = match signal {
        CallbackSignal::Heartbeat => {
            // "Sends a heartbeat … to indicate that the external system is still processing":
            // the callback stays open and the next heartbeat is due that span from now. The
            // whole callback's own timeout is not moved by it.
            callback.heartbeat_due = callback
                .heartbeat_timeout_seconds
                .and_then(|seconds| u64::try_from(seconds).ok())
                .and_then(|seconds| now.checked_add(Duration::from_secs(seconds)));
            return Ok(());
        }
        CallbackSignal::Succeeded(result) => {
            callback.state = CALLBACK_STATE_SUCCEEDED.to_string();
            callback.result = result.clone();
            callback.timeout_due = None;
            callback.heartbeat_due = None;
            callback.ended = Some(now);
            durable_steps::Checkpoint {
                operation: CALLBACK_TYPE.to_string(),
                action: durable_steps::SUCCEED_ACTION.to_string(),
                id: Some(operation),
                name,
                attempt: 1,
                payload: result.clone(),
                ..durable_steps::Checkpoint::default()
            }
        }
        CallbackSignal::Failed(error) => {
            callback.state = CALLBACK_STATE_FAILED.to_string();
            callback.error = error.clone();
            callback.timeout_due = None;
            callback.heartbeat_due = None;
            callback.ended = Some(now);
            durable_steps::Checkpoint {
                operation: CALLBACK_TYPE.to_string(),
                action: durable_steps::FAIL_ACTION.to_string(),
                id: Some(operation),
                name,
                attempt: 1,
                // `CallbackFailedDetails$Error` is REQUIRED, so a failure that carried no
                // error object reports the envelope with none inside it.
                error: Some(error.clone().unwrap_or_default()),
                ..durable_steps::Checkpoint::default()
            }
        }
    };
    durable_steps::append_checkpoint(execution, &checkpoint, now);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// RULE: the seam the run reads a callback over tells the reader two things about one
    /// answer — whether the callback is still WAITING, and whether the host waited inside the
    /// reading — and says them about the answer it was given rather than about any one shape of
    /// it.
    ///
    /// The rows differ along what the rule generalises over: the state the answer reports, an
    /// answer that reports no state at all (the refusal of the call, the id a mint answered),
    /// and an answer that is no document.
    #[test]
    fn an_answer_says_whether_the_callback_waits_and_whether_the_host_waited() {
        // (case, the answer, whether it reports a callback still waiting)
        let rows: &[(&str, ::serde_json::Value, bool)] = &[
            (
                "a callback no client has signalled",
                ::serde_json::json!({ "state": CALLBACK_STATE_WAITING }),
                true,
            ),
            (
                "a callback a client completed",
                ::serde_json::json!({ "state": CALLBACK_STATE_SUCCEEDED, "result": "{}" }),
                false,
            ),
            (
                "a callback a client failed",
                ::serde_json::json!({ "state": CALLBACK_STATE_FAILED }),
                false,
            ),
            (
                "a callback whose window closed",
                ::serde_json::json!({ "state": CALLBACK_STATE_TIMED_OUT }),
                false,
            ),
            (
                "the id a mint answered, which reports no state",
                ::serde_json::json!({ "callbackId": "Zm9v" }),
                false,
            ),
            (
                "the refusal of the call itself",
                ::serde_json::json!({ "refused": "this run holds no such callback" }),
                false,
            ),
        ];
        for (case, answer, waiting) in rows {
            let document = answer.to_string();
            assert_eq!(
                answer_is_still_waiting(&document),
                *waiting,
                "case {case:?}: expected the answer to report waiting={waiting}, got {document}"
            );
            // Whichever it reports, what the reading says about the callback survives the
            // member the seam adds, and that member is what the reader was told.
            for waited in [true, false] {
                let said = answer_waited(&document, waited);
                let read: ::serde_json::Value =
                    ::serde_json::from_str(&said).unwrap_or_default();
                assert_eq!(
                    read.get(ANSWER_WAITED_MEMBER).and_then(|m| m.as_bool()),
                    Some(waited),
                    "case {case:?}: expected the answer to say waited={waited}, got {said}"
                );
                for (member, value) in answer.as_object().into_iter().flatten() {
                    assert_eq!(
                        read.get(member),
                        Some(value),
                        "case {case:?}: expected {member:?} to survive, got {said}"
                    );
                }
            }
        }
        // An answer that is no document at all is left exactly as it was.
        let text = "not a document";
        assert_eq!(
            answer_waited(text, true),
            text,
            "case {:?}: expected the answer to travel as written, got {:?}",
            "an answer that is no document",
            answer_waited(text, true)
        );
    }
}
